#[test] fn case_0254() {
let position=Position::from_fen("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w - - 0 1").unwrap();
let mut root=RootContext::neutral(&position);
root.values=[[100,300,310,500,900],[100,300,310,500,900]];root.squares=[[[0;64];5];2];
let influence=Influence::build(&position);let mut learned=Learning::default();
learned.killers[3]=[None,None].map(|x|x.unwrap_or(Move::NONE));
learned.killers[1]=[None,None].map(|x|x.unwrap_or(Move::NONE));
let original:Vec<Move>=vec![];let mut list=MoveList::new();for &m in &original {list.push(m);}
tactical::order_by(&mut list,&mut OrderingScratch::new(),|candidate|policy::priority(&position,&root,&influence,&learned,3,None,candidate));
let actual:Vec<usize>=list.as_slice().iter().map(|m|original.iter().position(|x|x==m).unwrap()).collect();
assert_eq!(actual,vec![]);
}
